# Let's check complete multipartite graphs.
def get_complete_multipartite_stats(n, parts):
    # n vertices, parts is a list of sizes
    adj = {}
    nodes = []
    for i, size in enumerate(parts):
        for j in range(size):
            nodes.append((i, j))

    for i in range(len(nodes)):
        adj[nodes[i]] = set()
        for j in range(len(nodes)):
            if i == j: continue
            if nodes[i][0] != nodes[j][0]:
                adj[nodes[i]].add(nodes[j])

    f = count_triangles(adj)
    g = count_tetrahedra(adj)
    return f, g

# Iterate over partitions of n for small n
def get_all_partitions(n):
    def part(n, min_val=1):
        if n == 0: yield []
        for i in range(min_val, n + 1):
            for p in part(n - i, i):
                yield [i] + p
    return list(part(n))

max_ratio = 0
for n in range(4, 15):
    for p in get_all_partitions(n):
        f, g = get_complete_multipartite_stats(n, p)
        if f > 0:
